<div class="fkpis">${[['Active clients','2','1 proposal · 1 lead'],['Live funnels','4','2 proposed · 11 total'],['Planned revenue / mo','$70.7k','+ £13.2k · live funnels'],['Agency MRR','$3,700','retainers + recurring fees']].map(([l,v,s])=>`<div><small>${l}</small><b>${v}</b><span>${s}</span></div>`).join('')}</div>
