const fedTop=(f,c,m)=>`<header class="ftop ed"><a class="iconbtn" href="#/fmp/funnels" aria-label="Back">${ic('right',18).replace('<svg','<svg style="transform:scaleX(-1)"')}</a><div class="r-wrap"><button class="iconbtn" data-act="railmenu" aria-label="Apps">${ic('grid',17)}</button>${appMenu('fmp')}</div><nav class="fcrumbs"><a href="#/fmp/client/${c[0]}">${c[1]}</a><span class="sep">/</span><b>${f[1]}</b></nav><button class="fbtn sm">Scenario: Baseline${ic('down',12)}</button><span class="fsaved">${ic('check',12,'',2.6)}Saved</span><span class="grow"></span><div class="fseg"><a href="#/fmp/funnel/${f[0]}" aria-pressed="${m==='map'}">${ic('map',13)}Map</a><a href="#/fmp/funnel/${f[0]}/reports" aria-pressed="${m==='reports'}">${ic('chart',13)}Reports</a></div><span class="grow"></span><button class="iconbtn sm" aria-label="Undo">${ic('undo',16)}</button><button class="iconbtn sm" aria-label="Redo">${ic('redo',16)}</button><button class="fbtn sm" data-act="toast:Tidy up: lines the map up neatly.">${ic('sparkle',13)}Tidy up</button><button class="iconbtn sm" aria-label="Comments">${ic('msg',16)}</button><button class="iconbtn sm" aria-label="History">${ic('hist',16)}</button><button class="iconbtn sm" aria-label="Present" data-act="toast:Present: full screen, frame by frame.">${ic('play',16)}</button><button class="fbtn pri sm" data-act="fshare">${ic('share',13)}Share</button></header>`;
Object.assign(ACT,{fctab:v=>{FMV.tab=v;draw()},fstab:v=>{FMV.stab=v;draw()},fview:v=>{FMV.view=v;draw()},fins:v=>{FMV.ins=v;draw()},fsearch:()=>{US.scope='fmp';usOpen()},
fnewfunnel:()=>dlg({title:'New funnel',body:`<div class="field" style="margin-top:12px"><label>Name</label><input placeholder="e.g. Quiz funnel"></div><div class="field"><label>Belongs to</label><select><option>Internal (${oname()})</option>${FC.map(c=>`<option>${c[1]}</option>`).join('')}</select></div><div class="field"><label>Start from</label><select><option>Blank map</option><option>Tripwire template</option><option>Quiz template</option></select></div>`,acts:[['Cancel','noop'],['Create funnel','nav:fmp/funnel/pt','primary']]}),
fnewclient:()=>dlg({title:'New client',body:`<div class="field" style="margin-top:12px"><label>Client name</label><input placeholder="e.g. Sam Carter"></div><div class="row2"><div class="field"><label>Business</label><input></div><div class="field"><label>Email</label><input type="email"></div></div><div class="field"><label>Status</label><select><option>Lead</option><option>Proposal</option><option>Active</option></select></div><p class="hint">${ic('refresh',13)} Saved once and shared: it also appears in the Clients app. If a client with this email exists, we link to it instead of making a copy.</p>`,acts:[['Cancel','noop'],['Create client','toast:Client created in both Funnel Mapper and Clients.:ok','primary']]}),
fshare:()=>dlg({title:'Share funnel',body:`${[['Hide numbers',0],['Let comments',1],['Let edit',0]].map(([l,o])=>`<div class="tg-row">${l}<button class="toggle" role="switch" aria-checked="${!!o}" data-act="tgl" aria-label="${l}"></button></div>`).join('')}<div class="field"><label>Link expires</label><select><option>Never</option><option>In 7 days</option></select></div>`,acts:[['Cancel','noop'],['Create link','toast:Link created: view only · comments on · no expiry.:ok','primary']]})});
SEARCH.push(()=>org()==='l2f'?[...FF.map(f=>({app:'fmp',t:f[1],s:fcl(f[2])[1]+' · '+f[3],href:'fmp/funnel/'+f[0]})),...FC.map(c=>({app:'fmp',t:c[1],s:'FMP client · '+c[3],href:'fmp/client/'+c[0]}))]:[]);
